import { useState } from "react";
import type { Contact } from "@daice-chain/core";
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

/**
 * Compact table-cell variant of ContactPicker: shows just the name inline,
 * opening a small popover with name + email (plus suggestions) on click.
 * Used for the asset table's "Generated by" column (the spec's `generatedBy`
 * field — see spec/README.md §2.3) so most edits don't require opening the
 * full detail dialog. See docs/planning/04-editor.md Part C.
 */
export function InlineContactCell({
  value,
  suggestions,
  onChange,
  placeholder = "Generated by",
  invalid = false,
  invalidTitle,
}: {
  value: Contact | undefined;
  suggestions: Contact[];
  onChange: (contact: Contact | undefined) => void;
  placeholder?: string;
  /** Marks the cell as failing schema validation — e.g. required-when-AI and left blank. */
  invalid?: boolean;
  invalidTitle?: string;
}) {
  const [open, setOpen] = useState(false);
  const [draftName, setDraftName] = useState(value?.name ?? "");
  const [draftEmail, setDraftEmail] = useState(value?.email ?? "");

  function commit() {
    const name = draftName.trim();
    onChange(name ? { name, email: draftEmail.trim() || undefined } : undefined);
  }

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (!next) commit();
        else {
          setDraftName(value?.name ?? "");
          setDraftEmail(value?.email ?? "");
        }
        setOpen(next);
      }}
    >
      <PopoverAnchor asChild>
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            setOpen(true);
          }}
          className={cn(
            "w-full truncate rounded px-1.5 py-0.5 text-left text-sm hover:bg-accent",
            !value?.name && "text-muted-foreground",
            invalid && "ring-1 ring-inset ring-destructive/70 bg-destructive/5 text-destructive",
          )}
          title={invalid ? invalidTitle : value?.name || placeholder}
        >
          {value?.name || placeholder}
        </button>
      </PopoverAnchor>
      <PopoverContent className="flex w-56 flex-col gap-2 p-2" onOpenAutoFocus={(e) => e.preventDefault()}>
        <Input
          autoFocus
          placeholder="Name"
          value={draftName}
          onChange={(e) => setDraftName(e.target.value)}
          onKeyDown={(e) => {
            e.stopPropagation();
            if (e.key === "Enter") {
              commit();
              setOpen(false);
            }
            if (e.key === "Escape") setOpen(false);
          }}
        />
        <Input
          type="email"
          placeholder="Email (optional)"
          value={draftEmail}
          onChange={(e) => setDraftEmail(e.target.value)}
          onKeyDown={(e) => {
            e.stopPropagation();
            if (e.key === "Enter") {
              commit();
              setOpen(false);
            }
            if (e.key === "Escape") setOpen(false);
          }}
        />
        {suggestions.length > 0 && (
          <div className="flex flex-col gap-0.5 border-t border-border pt-1.5">
            {suggestions.slice(0, 6).map((contact, index) => (
              <button
                key={`${contact.name}-${contact.email ?? ""}-${index}`}
                type="button"
                className="truncate rounded px-1.5 py-1 text-left text-xs hover:bg-accent"
                onMouseDown={(e) => {
                  e.preventDefault();
                  onChange(contact);
                  setOpen(false);
                }}
              >
                {contact.name}
                {contact.email ? ` · ${contact.email}` : ""}
              </button>
            ))}
          </div>
        )}
      </PopoverContent>
    </Popover>
  );
}
